import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"汉上易传卷十一","description":"汉上易传 - 汉上易传卷十一","frontmatter":{"title":"汉上易传卷十一","description":"汉上易传 - 汉上易传卷十一"},"headers":[],"relativePath":"zh/classics/hanshang/012.md","filePath":"zh/classics/hanshang/012.md"}'),l={name:"zh/classics/hanshang/012.md"};function c(o,e,i,d,h,p){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"汉上易传卷十一",tabindex:"-1"},[r("汉上易传卷十一 "),a("a",{class:"header-anchor",href:"#汉上易传卷十一","aria-label":"Permalink to “汉上易传卷十一”"},"​")],-1),a("p",null,"杂卦专以刚柔升降反复取义，又揉杂众卦以畅无穷之用。而归藏、连山，三代之易皆在其中。百世之后，有圣人作，不外是也。康节曰：乾坤三变，坎离不动，故太玄准之以玄冲、玄错，",-1),a("p",null,"乾刚坤柔，比乐师忧，临、观之义，或与或求。屯见而不失其居，蒙杂而著。震，起也；艮，止也。损、益，盛衰之始也。大畜，时也，无妄灾也。萃聚而升不来也。谦轻而豫怠也。噬嗑食也。贲无色也。兑见而巽伏也。随无故也。蛊则饬也。剥烂也。复反也。晋昼也。明夷诛也。井通而困相遇也。咸速也。恒久也。涣离也。节止也。解缓也。蹇难也。睽外也。家人内也。否泰反其类也。大壮则止。遁则退也。大有，众也。同人，亲也。革，去故也。鼎，取新也。小过，过也。中孚，信也。丰，多故也。亲寡。旅也。离上而坎下也。小畜，寡也。履，不处也。需，不进也。讼，不亲也。大过，颠也。遘，遇也。柔遇刚也。渐，女归待男行也。颐，养正也。既济，定也。归妹，女之终也。未济，男之穷也。夬，决也。刚决柔也。君子道长，小人道忧也。",-1),a("p",null,"乾坤，易之门。凡刚皆乾也，凡柔皆坤也。刚柔相杂，乃成诸卦，故曰乾刚坤柔。比得位而众比之，故乐。师犯难而众从之，故忧。忧乐以天下也。临之九二在下，四阴与之，故能以大临小。观之九五在上，四阴求之，故能以上观下。或与或求，乃成临观之义。屯自震变四之五虽见于屯也，而不失其所居，所以大亨。欤蒙自坎变，五之上阴阳相杂，虽杂也，而九自著见，阴岂能蒙之所以蒙亨。欤。阳起于坤而出震，则静者动。阳止于艮而入坤，则动者静。故起莫如震，止莫如艮也。损以九三为上，由泰而损始衰者也。益以九四益初，由否而益始盛者也。故损益盛衰之始也。大畜以四五之柔而畜三阳，时也。无妄九五六二中正，而三四上爻为无妄之疾灾也。关子明曰：无妄而灾者，灾也。有妄而灾者，其所宜也，非灾之者也。萃，二阳萃于上，升，二阳升于下。升者，往也。升往则不来矣。不来者，必聚于上也。气之方升，谁能遏之？故曰萃聚而升不来也。谦自上降三，豫自初升四，谦故降也。轻豫故怠而止，故曰谦轻而豫怠也。噬嗑，除间者也。四为颐，中有物，故曰噬嗑食也。贲自泰来，本无色也。刚柔交错，然后有文，故曰贲无色也。阴随阳升，说而见乎外，故曰兑见也。阳随阴降，巽而伏乎内，故曰巽伏也。施说之道，小者亦伸，处巽之时，大者亦屈，无非天也。随，随时也，以是为正，故曰随无故也。蛊，坏也。二往之五，饬蛊之道，故曰蛊则饬也。剥，烂也。五阴溃于内也。复，反也。剥，上反于下也。晋之明进而至于昼，明夷之明降而至于诛。夷，诛也。其明熄矣，非诛之象乎。泰初之五，往来不穷，故曰井通。否上之二阳遇阴而见揜，故曰困相遇也。或往而通，或来而困，唯其时也。以刚下柔，其感必速，故曰咸感也。刚上柔下，可以持久，故曰恒久也。涣三阳涣离，故曰涣离也。节三阳止而不去，故曰节止也。阳离则三阴散，阳止则三阴来。阳者，阴之表也。蹇二往五涉难也，故曰蹇难也。解五来二复吉也，故曰解，缓也。来者为缓，则往者当夙，故曰有攸往，夙吉。关子明曰：明乎外者物自聧，故曰聧外也。明乎内者家自齐，故曰家人内也。君子泰则小人否，小人泰则君子否，故曰否泰反其类也。四阳并进，六五以和易待之，可以止而仕也，故曰大壮则止。四阳偕往，二阴在内而执其柄，可以退而去也，故曰遁则退也。同人六二得中得位而同乎人，同乎人则人亦亲之，故曰同人亲也。大有六五柔得尊位而有其众，有其众则众亦归之，故曰大有众也。水火相革，革已废也，故曰革去故也。以木巽火，火方兴也，故曰鼎取新也。功成者退，方来者进，一去一取，天之道也。小过二阳在内，动而止，小者过也，故曰小过过也。中孚二阴在内，伏而说，小者信也，故曰中孚信也。丰泰二之四进退不得其所，多故也。多故则难处，故曰丰多故也。旅，否三之五，失位无应，以其旅于外也。旅外者，不如在内之为安，故曰亲寡旅也。礼，多故也，故四五相错，然后有庆。亲寡旅也，故五动二应而后有誉。离火炎上也，故阳爻多凶。坎水趣下也，故阴爻多凶。坎离相济者也。小畜五阳而畜一阴，所畜者寡，故曰小畜寡也。履一柔而履二刚，不处为善，故曰履不处也。需险在前，三阳需时而不进。关子明曰：履而不处者，其周公乎。需而不进者，其仲尼乎。险在下而阳上行相过者也。故曰讼不亲也。自大过颠也，而下简册错乱，当曰颐养正也。大过颠也。遘，遇也。遘当作姤，柔遇刚也。夬，决也，刚决柔也。君子道长，小人道忧也。渐，女归，待男行也。归妹，女之终也。既济，定也。未济，男之穷也。颐一阳在上而养四，阴，正也，故其卦以下养上为颠。大过一阴在上，四阳无所托，颠也。故其卦初阴承阳，无失位之凶。阴宜在下也。姤以一柔而遇五刚，故曰姤遇也，柔遇刚也。夬以五刚而决一柔，故曰夬决也，刚决柔也。姤，小人道长，君子道忧也，故系于金柅。夬，君子道长，小人道忧也，故无号之凶。女以外为归，乾男下而迎三，然后坤女行而归，故曰渐归，待男行也。归妹以三易四，男行而女从，夫妇之正也。上六无应，守正而终不改之义也。故曰归妹，女之终也。既济虞翻曰：六爻得位，定也。故曰既济，定也。未济伊川曰：三阳失位，故曰未济，男之穷也。周易杂卦传第十一。",-1)])])}const f=s(l,[["render",c]]);export{_ as __pageData,f as default};
